WITH order_summary AS (SELECT order_id, MAX(shipped_date) AS last_shipped_date, MAX(cost) AS max_cost FROM shipments GROUP BY order_id) SELECT orders.id, orders.channel, orders.discount, order_summary.last_shipped_date, order_summary.max_cost FROM orders JOIN order_summary ON orders.id = order_summary.order_id WHERE order_summary.max_cost > 93 ORDER BY order_summary.last_shipped_date, discount;
